const b=$json.body??$json;
const requestId=String(b.request_id??'wf125-'+Date.now());
const leadId=b.lead_id??null, propertyId=b.property_id??null, dealId=b.deal_id??null;
const agreementType=String(b.agreement_type??'').toLowerCase();
const executionState=String(b.execution_state??'').toLowerCase();
const agreedPrice=Number(b.agreed_price??NaN), mao=Number(b.mao_ceiling??NaN);
const evidence=b.acceptance_evidence??b.signed_evidence??null, dnc=Boolean(b.dnc);
const missing=[]; for(const [k,v] of Object.entries({lead_id:leadId,property_id:propertyId,deal_id:dealId,agreement_type:agreementType,execution_state:executionState})) if(v===null||v===undefined||v==='') missing.push(k);
let status='blocked',nextState='blocked',route='human_review',reason='Transaction readiness requires review';
if(dnc){status='suppressed';nextState='suppressed';route='none';reason='DNC/STOP suppression applies to communication; transaction record is retained';}
else if(missing.length){status='blocked';nextState='missing_transaction_inputs';reason='Required transaction identity or execution fields are missing';}
else if(!['executed','contract_executed'].includes(executionState)){status='blocked';nextState='contract_not_executed';reason='Agreement is not confirmed executed';}
else if(!evidence){status='human_review';nextState='execution_evidence_review';reason='Executed state lacks sufficient acceptance/signature evidence';}
else if(Number.isFinite(mao)&&(!Number.isFinite(agreedPrice)||agreedPrice>mao)){status='blocked';nextState='economics_violation';reason='Agreed price exceeds MAO ceiling';}
else{status='ready_for_closing_review';nextState='closing_coordination';route='wf-042-closing-coordination';reason='Executed transaction passed core readiness gates and is ready for closing coordination';}
const id='transaction-readiness:'+dealId+':'+requestId+':v1;
const requirements=['title/ownership verification','closing attorney/title company confirmation','executed agreement copy','seller identity verification','property identity verification'];
if(agreementType==='assignment') requirements.push('assignee/buyer confirmation','assignment fee confirmation');
if(agreementType==='novation') requirements.push('novation/replacement agreement requirements');
if(agreementType==='double_close') requirements.push('funding source and closing-to-closing coordination');
if(b.closing_date??b.target_closing_date) requirements.push('critical closing date tracking');
return [{json:{workflow:'WF-125',workflow_version:'1.0',request_id:requestId,transaction_readiness_id:id,lead_id:leadId,property_id:propertyId,deal_id:dealId,agreement_type:agreementType,execution_state:status==='ready_for_closing_review'?'executed':executionState,status,next_state:nextState,route,reason,agreed_price:Number.isFinite(agreedPrice)?agreedPrice:null,mao_ceiling:Number.isFinite(mao)?mao:null,spread_to_mao:Number.isFinite(mao)&&Number.isFinite(agreedPrice)?mao-agreedPrice:null,closing_date:b.closing_date??b.target_closing_date??null,buyer_id:b.buyer_id??b.assignee_id??null,requirements,missing_items:missing,guardrails:{executed_agreement_required:true,never_exceed_mao:true,no_invented_title_or_legal_facts:true,human_closing_review_required:true,dnc_suppresses_communication_not_transaction_record:true},crm_activity:{activity_type:'transaction_readiness',subject:'WF-125 transaction readiness — '+status,lead_id:leadId,property_id:propertyId,deal_id:dealId,external_id:id,external_source:'wholesaling-os-transaction',metadata:{status,next_state,route,reason,agreement_type,execution_state}}}}];
